def backfill_legacy():
    import json

    bind = op.get_bind()
    metadata = sa.MetaData()
    tables = {
        name: sa.Table(name, metadata, autoload_with=bind)
        for name in (
            "requests",
            "request_items",
            "purchase_orders",
            "suppliers",
            "order_lines",
            "request_revisions",
        )
    }
    requests, items, orders = (
        tables[name] for name in ("requests", "request_items", "purchase_orders")
    )
    for record in bind.execute(sa.select(requests)).mappings():
        if record["status"] in {"approved", "ordered", "partial", "received"}:
            bind.execute(
                requests.update().where(requests.c.id == record["id"]).values(approved_revision=1)
            )
        if record["status"] not in {"draft", "cancelled"}:
            lines = [
                dict(row)
                for row in bind.execute(
                    sa.select(items).where(items.c.request_id == record["id"])
                ).mappings()
            ]
            bind.execute(
                tables["request_revisions"]
                .insert()
                .values(
                    request_id=record["id"],
                    revision=1,
                    snapshot=json.dumps(
                        {"legacy_reconstructed": True, "request": dict(record), "items": lines}
                    ),
                    created_at=record["created_at"],
                )
            )
    for order in bind.execute(sa.select(orders)).mappings():
        supplier = (
            bind.execute(
                sa.select(tables["suppliers"]).where(
                    tables["suppliers"].c.id == order["supplier_id"]
                )
            )
            .mappings()
            .one()
        )
        bind.execute(
            orders.update()
            .where(orders.c.id == order["id"])
            .values(
                supplier_name=supplier["name"],
                supplier_contact=supplier["contact"],
                selection_reason="Migrated v1 order. Agreed line prices were not recorded; original total is preserved.",
            )
        )
        for item in bind.execute(
            sa.select(items).where(items.c.request_id == order["request_id"])
        ).mappings():
            bind.execute(
                tables["order_lines"]
                .insert()
                .values(
                    order_id=order["id"],
                    request_item_id=item["id"],
                    name=item["name"],
                    unit="unit",
                    quantity=item["quantity"],
                    unit_price=None,
                    received_quantity=item["received_quantity"],
                )
            )
